css.stylesheet:
html {
	--mobile-scale: 1.41;
	--mobile-padding-offset: 0;
}

body {
	--swatch-1: rgba(0, 0, 0, 0.85);
	--swatch-2: rgba(0, 0, 0, 0.75);
	--swatch-3: rgba(0, 0, 0, 0.6);
	--swatch-4: rgba(0, 0, 0, 0.4);
    --swatch-5: rgba(0, 0, 0, 0.25);
	--swatch-6: #1ba539;
	background-color: rgba(123, 13, 13, 0);
}

body.mobile {
}

a:active,
.linked:active,
.zoomable::part(media):active {
	opacity: 0.7;
}

.page a.active {
	color: #ff0000;
}

sub {
	position: relative;
	vertical-align: baseline;
	top: 0.3em;
}

sup {
	position: relative;
	vertical-align: baseline;
	top: -0.4em;
}

.small-caps {
	font-variant: small-caps;
    text-transform: lowercase;
}

ol {
	margin: 0;
	padding: 0 0 0 2.5em;
}

ul {
	margin: 0;
	padding: 0 0 0 2.0em;
}

ul.lineated {
	margin: 0;
	padding: 0;
	list-style-type: none;
	margin: 0 0 0 3em;
	text-indent: -3em;
}

blockquote {
	margin: 0;
	padding: 0 0 0 2em;
}

hr {
	background: rgba(0, 0, 0, 0.75);
	border: 0;
	height: 1px;
	display: block;
    margin-top: 1rem;
    margin-bottom: 1rem;
}

.content {
	border-color: rgba(0, 0, 0, 0.85);
	border-width: 0.0rem;
	border-style: solid;
	border-radius: 0.1rem;
	margin: 0.0rem;
	margin-left: 20.9rem;
}

bodycopy {
	font-size: 1.45rem;
	font-weight: 400;
	color: rgba(0, 0, 0, 0.75);
	font-family: "Monument Grotesk Variable";
	font-style: normal;
	line-height: 1.55;
	letter-spacing: 0em;
	display: block;
	font-variation-settings: 'slnt' 0, 'MONO' 0;
	font-feature-settings: "ss02", "ss04";
}

bodycopy a {
	color: rgba(0, 0, 0, 0.75);
	text-decoration: none;
}

bodycopy a:hover {
     color: #310fce;
}

h1 {
	font-family: "Monument Grotesk Variable";
	font-style: normal;
	font-weight: 400;
	margin: 0;
	font-size: 2.10rem;
	line-height: 0.5;
	color: rgba(0, 0, 0, 0.85);
	letter-spacing: 0em;
	font-variation-settings: 'slnt' 0, 'MONO' 0;
}

h1 a {
	color: rgba(0, 0, 0, 0.85);
	text-decoration: none;
}

h1 a:hover {
}

.mobile h1 {
	font-size: 3rem;
}

.mobile h1 a {
	text-decoration: none;
}

h2 {
	font-family: "Monument Grotesk Variable";
	font-style: normal;
	font-weight: 500;
	margin: 0;
	color: rgba(0, 0, 0, 0.85);
	font-size: 3.60rem;
	line-height: 1;
	letter-spacing: 0em;
	font-variation-settings: 'slnt' 0, 'MONO' 0;
}

h2 a {
	color: rgba(0, 0, 0, 0.85);
	text-decoration: none;
}

h2 a:hover {
}

.caption {
	font-size: 1.45rem;
	font-weight: 500;
	color: rgba(0, 0, 0, 0.85);
	font-family: "Monument Grotesk Variable";
	font-style: normal;
	line-height: 1.2;
	letter-spacing: 0em;
	display: block;
	font-variation-settings: 'slnt' 0, 'MONO' 0;
}

.mobile .caption {
	font-size: 1.3rem;
}

.caption a {
	color: rgba(2, 21, 93, 0.85);
	text-decoration: underline;
}

.caption a:hover {
}

media-item .caption {
	margin-top: .5em;
}

gallery-grid .caption,
gallery-columnized .caption,
gallery-justify .caption {
	margin-bottom: 2em;
}

[thumbnail-index] .caption {
	text-align: center;
}

[thumbnail-index] .caption .tags {
	margin-top: 0.25em;
}

.page {
	justify-content: center;
	background-color: rgba(31, 36, 35, 0);
	min-height: var(--viewport-height);
}

.page-content {
	padding: 0rem;
	text-align: left;
	background-color: rgba(121, 66, 66, 0);
	border-width: 0.0rem;
	border-color: rgba(0,0,0,.85);
	border-style: solid;
	border-radius: 0.0rem;
	box-shadow: 0rem 0rem 0rem 0rem rgba(20, 54, 224, 0.25);
	align-items: flex-start;
}

.mobile [id] .page-layout {
	max-width: 100%;
}

.mobile [id] .page-content {
}

.page-layout {
	align-items: flex-start;
	max-width: 100%;
	padding: 0.0rem;
	padding-left: 1.3rem;
}

media-item::part(media) {
	border: 0;
	padding: 0;
}

.quick-view {
	height: 100%;
	width: 100%;
	padding: 3rem;
	margin-top: auto;
	margin-right: auto;
	margin-bottom: auto;
	margin-left: auto;
}

.quick-view-background {
	background-color: #ffffff;
}

.quick-view .caption {
	color: rgba(255, 255, 255, 1.0);
	padding: 20px 0;
	text-align: center;
	transition: 100ms opacity ease-in-out;
	position: absolute;
	bottom: 0;
	left: 0;
	right: 0;
}

.quick-view .caption-background {
	padding: 0.5rem 1rem;
	display: inline-block;
	background: rgba(0, 0, 0, 0.5);
	border-radius: .5rem;
	text-align: left;
	max-width: 50rem;
}

.mobile .quick-view {
	width: 100%;
	height: 100%;
	margin: 0;
	padding: 10px;
}

.mobile .quick-view .caption {
	padding: 10px 0;
}

